/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { readFileSync } from 'node:fs'
import { parseDocument } from './parse.js'
import { renderJson, renderKeys } from './render.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'json' && mode !== 'keys') {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const text = readFileSync(0, 'utf8')
let out
try {
  const root = parseDocument(text)
  out = mode === 'json' ? renderJson(root) : renderKeys(root)
} catch (e) {
  if (e && e.isConfigError) {
    process.stderr.write(`error: line ${e.line}: ${e.message}\n`)
    process.exit(2)
  }
  throw e
}
process.stdout.write(out)
"}

{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20261020T225235Z/cell-8qfwDE/src/render.js","content":"function cmp(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d !== 0) return d
  }
  return x.length - y.length
}

const sortedKeys = (node) => [...node.map.keys()].sort(cmp)

function json(node, indent) {
  const pad = '  '.repeat(indent + 1)
  const end = '  '.repeat(indent)
  switch (node.type) {
    case 'table': {
      const keys = sortedKeys(node)
      if (keys.length === 0) return '{}'
      const parts = keys.map((k) => `${pad}${JSON.stringify(k)}: ${json(node.map.get(k), indent + 1)}`)
      return `{\n${parts.join(',\n')}\n${end}}`
    }
    case 'array': {
      if (node.items.length === 0) return '[]'
      const parts = node.items.map((v) => pad + json(v, indent + 1))
      return `[\n${parts.join(',\n')}\n${end}]`
    }
    default:
      return JSON.stringify(node.value)
  }
}

export function renderJson(root) {
  return json(root, 0) + '\n'
}

export function renderKeys(root) {
  const lines = []
  const walk = (node, path) => {
    if (node.type === 'table') {
      for (const k of sortedKeys(node)) {
        const p = path === null ? k : `${path}.${k}`
        const child = node.map.get(k)
        lines.push(`${p} ${child.type}`)
        walk(child, p)
      }
    } else if (node.type === 'array') {
      node.items.forEach((child, i) => {
        const p = `${path}[${i}]`
        lines.push(`${p} ${child.type}`)
        walk(child, p)
      })
    }
  }
  walk(root, null)
  return lines.map((l) => l + '\n').join('')
}
"}

{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20261020T225235Z/cell-8qfwDE/src/parse.js","content":"class ConfigError extends Error {
  constructor(message) {
    super(message)
    this.isConfigError = true
    this.line = 0
  }
}
const fail = (m) => {
  throw new ConfigError(m)
}

const newTable = (path) => ({ type: 'table', map: new Map(), path, headed: false })
const BARE = /[A-Za-z0-9_-]/
const isWs = (c) => c === ' ' || c === '\t'
const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class LineParser {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  ws() {
    while (this.i < this.s.length && isWs(this.s[this.i])) this.i++
  }
  /** True at end of line or at a comment start. */
  atEnd() {
    return this.i >= this.s.length || this.s[this.i] === '#' || this.s[this.i] === ';'
  }
  name() {
    const s = this.s
    const c = s[this.i]
    if (c === '"') return this.basic()
    if (c === "'") return this.literal()
    const st = this.i
    while (this.i < s.length && BARE.test(s[this.i])) this.i++
    if (this.i === st) fail('expected a name')
    return s.slice(st, this.i)
  }
  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.s[this.i] === '.') {
        this.i++
        this.ws()
        parts.push(this.name())
      } else {
        this.i = save
        return parts
      }
    }
  }
  literal() {
    const end = this.s.indexOf("'", this.i + 1)
    if (end < 0) fail('unterminated string')
    const v = this.s.slice(this.i + 1, end)
    this.i = end + 1
    return v
  }
  basic() {
    const s = this.s
    let out = ''
    this.i++
    for (;;) {
      if (this.i >= s.length) fail('unterminated string')
      const c = s[this.i]
      if (c === '"') {
        this.i++
        return out
      }
      if (c === '\\') {
        if (this.i + 1 >= s.length) fail('unterminated string')
        const e = String.fromCodePoint(s.codePointAt(this.i + 1))
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (e in map) {
          out += map[e]
          this.i += 2
        } else if (e === 'u') {
          const h = s.slice(this.i + 2, this.i + 6)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 6
        } else fail(`invalid escape \\${e}`)
      } else {
        out += c
        this.i++
      }
    }
  }
  value(prefix) {
    const s = this.s
    if (this.atEnd()) fail('expected a value')
    const c = s[this.i]
    if (c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"') return { type: 'string', value: this.basic() }
    if (c === "'") return { type: 'string', value: this.literal() }
    if (c === '[') return this.array(prefix)
    if (c === '{') return this.inline(prefix)
    const st = this.i
    while (
      this.i < s.length &&
      !isWs(s[this.i]) &&
      !',]};'.includes(s[this.i])
    )
      this.i++
    const tok = s.slice(st, this.i)
    if (tok === 'true' || tok === 'false') return { type: 'boolean', value: tok === 'true' }
    if (INT.test(tok)) return { type: 'integer', value: Number(tok.replace(/_/g, '')) }
    if (FLOAT.test(tok)) return { type: 'float', value: Number(tok.replace(/_/g, '')) }
    fail(`invalid value ${tok}`)
  }
  array(prefix) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.s[this.i] === ']') {
        this.i++
        return { type: 'array', items, aot: false }
      }
      items.push(this.value(prefix))
      this.ws()
      if (this.s[this.i] === ',') this.i++
      else if (this.s[this.i] === ']') continue
      else fail('unterminated array')
    }
  }
  inline(prefix) {
    this.i++
    const tbl = newTable(prefix)
    this.ws()
    if (this.s[this.i] === '}') {
      this.i++
      return tbl
    }
    for (;;) {
      this.ws()
      if (this.i >= this.s.length) fail('unterminated inline table')
      const keys = this.dotted()
      this.ws()
      if (this.s[this.i] !== '=') fail('expected = in an inline table')
      this.i++
      this.ws()
      const v = this.value([...prefix, ...keys])
      assign(tbl, keys, v)
      this.ws()
      if (this.s[this.i] === ',') this.i++
      else if (this.s[this.i] === '}') {
        this.i++
        return tbl
      } else fail('unterminated inline table')
    }
  }
}

const pathStr = (p) => p.join('.')

/** Descend through one name on the way to a deeper node. */
function step(table, key, creating) {
  const path = [...table.path, key]
  let child = table.map.get(key)
  if (!child) {
    child = newTable(path)
    table.map.set(key, child)
    return child
  }
  if (child.type === 'table') return child
  if (child.type === 'array' && child.aot) return child.items[child.items.length - 1]
  fail(`${pathStr(path)} is not a table`)
}

function assign(table, keys, value) {
  let t = table
  for (let i = 0; i < keys.length - 1; i++) t = step(t, keys[i])
  const last = keys[keys.length - 1]
  if (t.map.has(last)) fail(`key ${pathStr([...t.path, last])} is defined twice`)
  fixPath(value, [...t.path, last])
  t.map.set(last, value)
}

/** Inline tables are built before their final location is known. */
function fixPath(node, path) {
  if (node.type === 'table') {
    node.path = path
    for (const [k, v] of node.map) fixPath(v, [...path, k])
  } else if (node.type === 'array') node.items.forEach((v) => fixPath(v, path))
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable([])
  let current = root
  lines.forEach((line, idx) => {
    try {
      current = doLine(line, root, current)
    } catch (e) {
      if (e.isConfigError) e.line = idx + 1
      throw e
    }
  })
  return root
}

function doLine(line, root, current) {
  const p = new LineParser(line)
  p.ws()
  if (p.atEnd()) return current
  if (p.s[p.i] === '[') return header(p, root, current)
  const keys = p.dotted()
  p.ws()
  if (p.s[p.i] !== '=') fail('expected key = value')
  p.i++
  p.ws()
  const v = p.value([...current.path, ...keys])
  p.ws()
  if (!p.atEnd()) fail('trailing text after a value')
  assign(current, keys, v)
  return current
}

function header(p, root, current) {
  const isArr = p.s[p.i + 1] === '['
  p.i += isArr ? 2 : 1
  p.ws()
  const keys = p.dotted()
  p.ws()
  const close = isArr ? ']]' : ']'
  if (p.s.startsWith(close, p.i)) p.i += close.length
  else fail('unterminated table header')
  p.ws()
  if (!p.atEnd()) fail('trailing text after a table header')
  let t = root
  for (let i = 0; i < keys.length - 1; i++) t = step(t, keys[i])
  const last = keys[keys.length - 1]
  const path = [...t.path, last]
  const existing = t.map.get(last)
  if (isArr) {
    if (!existing) {
      const fresh = newTable(path)
      t.map.set(last, { type: 'array', items: [fresh], aot: true })
      return fresh
    }
    if (existing.type !== 'array' || !existing.aot) fail(`${pathStr(path)} is not an array of tables`)
    const fresh = newTable(path)
    existing.items.push(fresh)
    return fresh
  }
  if (!existing) {
    const fresh = newTable(path)
    fresh.headed = true
    t.map.set(last, fresh)
    return fresh
  }
  if (existing.type !== 'table') fail(`${pathStr(path)} is not a table`)
  if (existing.headed) fail(`table ${pathStr(path)} is defined twice`)
  existing.headed = true
  return existing
}
"}

