import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let started = false
  let prev = null
  const num = (v, field, least) => {
    if (!INT.test(v) || BigInt(v) < BigInt(least)) {
      throw new Fail(`${field} must be an integer of at least ${least}`)
    }
    return BigInt(v)
  }
  const declName = (n) => {
    if (!NAME.test(n)) throw new Fail(`invalid policy name ${n}`)
  }
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const f = line.split(/\s+/)
    const d = f[0]
    try {
      if (d === 'bucket' || d === 'window' || d === 'route') {
        const want = d === 'bucket' ? 5 : d === 'window' ? 4 : 3
        const exp = d === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>'
          : d === 'window' ? 'expected window <name> <limit> <span>' : 'expected route <prefix> <policy>...'
        if (d === 'route' ? f.length < want : f.length !== want) throw new Fail(exp)
        if (started) throw new Fail('declarations must come before the first event')
        if (d === 'route') {
          if (!NAME.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
          if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
          for (const p of f.slice(2)) if (!policies.has(p)) throw new Fail(`unknown policy ${p}`)
          routes.set(f[1], f.slice(2))
        } else {
          declName(f[1])
          let p
          if (d === 'bucket') {
            const capacity = num(f[2], 'capacity', 1)
            const refill = num(f[3], 'refill', 0)
            const per = num(f[4], 'per', 1)
            p = { type: 'bucket', name: f[1], capacity, refill, per }
          } else {
            const limit = num(f[2], 'limit', 0)
            const span = num(f[3], 'span', 1)
            p = { type: 'window', name: f[1], limit, span }
          }
          if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
          policies.set(f[1], p)
        }
      } else if (d === 'event') {
        if (f.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = num(f[1], 'tick', 0)
        if (!NAME.test(f[2])) throw new Fail(`invalid key ${f[2]}`)
        if (prev !== null && tick < prev) throw new Fail(`tick ${tick} is before tick ${prev}`)
        prev = tick
        started = true
        events.push({ tick, key: f[2], tickStr: f[1] })
      } else {
        throw new Fail(`unknown directive ${d}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  return { policies, routes, events }
}

let out = ''
try {
  const { policies, routes, events } = parse(readFileSync(0, 'utf8'))
  const states = new Map()
  const stateFor = (p, key, tick) => {
    const k = p.name + '\0' + key
    let s = states.get(k)
    if (!s) {
      s = p.type === 'bucket' ? { units: p.capacity * p.per, last: tick } : { ticks: [] }
      states.set(k, s)
    }
    return s
  }
  const stats = new Map()
  let ta = 0, td = 0
  const prefixes = [...routes.keys()]
  for (const ev of events) {
    let best = null
    for (const pf of prefixes) if (ev.key.startsWith(pf) && (best === null || pf.length > best.length)) best = pf
    let denier = null
    if (best !== null) {
      const ps = routes.get(best).map((n) => policies.get(n))
      const ss = ps.map((p) => stateFor(p, ev.key, ev.tick))
      ps.forEach((p, i) => {
        const s = ss[i]
        if (p.type === 'bucket') {
          const cap = p.capacity * p.per
          s.units += p.refill * (ev.tick - s.last)
          if (s.units > cap) s.units = cap
          s.last = ev.tick
        } else {
          const cut = ev.tick - p.span
          s.ticks = s.ticks.filter((t) => t > cut)
        }
      })
      for (let i = 0; i < ps.length; i++) {
        const p = ps[i], s = ss[i]
        const ok = p.type === 'bucket' ? s.units >= p.per : BigInt(s.ticks.length) < p.limit
        if (!ok) { denier = p.name; break }
      }
      if (denier === null) {
        ps.forEach((p, i) => {
          if (p.type === 'bucket') ss[i].units -= p.per
          else ss[i].ticks.push(ev.tick)
        })
      }
    }
    const st = stats.get(ev.key) || { a: 0, d: 0 }
    stats.set(ev.key, st)
    if (denier === null) { st.a++; ta++ } else { st.d++; td++ }
    if (mode === 'replay') out += `${ev.tick} ${ev.key} ${denier === null ? 'allow' : 'deny ' + denier}\n`
  }
  if (mode === 'summary') {
    for (const k of [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
      out += `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}\n`
    }
    out += `total allowed=${ta} denied=${td}\n`
  }
} catch (e) {
  if (e instanceof Fail) {
    process.stderr.write(`error: ${e.message}\n`)
    process.exit(2)
  }
  throw e
}
process.stdout.write(out)
EOF
