{"command":"cat > src/cli.js <<'EOF'
#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { readFileSync } from 'node:fs'

function fail(msg, code = 2) {
  process.stderr.write(msg + '\n')
  process.exit(code)
}

const args = process.argv.slice(2)
const mode = args[0]
let workers = 0
if (mode === 'waves' || mode === 'explain') {
  if (args.length !== 1) fail('error: usage: cli.js waves|explain|pack <workers>')
} else if (mode === 'pack') {
  if (args.length !== 2) fail('error: usage: cli.js waves|explain|pack <workers>')
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else fail('error: usage: cli.js waves|explain|pack <workers>')

const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cost = new Map()
const deps = new Map()
const depUses = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    for (const x of w.slice(1)) depUses.push(x)
    if (!deps.has(w[1])) deps.set(w[1], new Set())
    for (const d of w.slice(2)) deps.get(w[1]).add(d)
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
})
