const eq = (a, b) => a.length === b.length && a.every((x, i) => x === b[i])

function changes(base, side, who) {
  const n = base.length
  const m = side.length
  const w = m + 1
  const L = new Int32Array((n + 1) * w)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      L[i * w + j] = base[i] === side[j] ? L[(i + 1) * w + j + 1] + 1 : Math.max(L[(i + 1) * w + j], L[i * w + j + 1])
    }
  }
  const out = []
  let i = 0
  let j = 0
  let cur = null
  const close = () => { if (cur) { cur.end = i; cur.lines = side.slice(cur.js, j); out.push(cur); cur = null } }
  const open = () => { if (!cur) cur = { who, start: i, js: j } }
  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) { close(); i++; j++ }
    else if (j >= m) { open(); i++ }
    else if (i >= n) { open(); j++ }
    else if (L[(i + 1) * w + j] >= L[i * w + j + 1]) { open(); i++ }
    else { open(); j++ }
  }
  close()
  return out
}

function sideLines(base, rs, re, cs) {
  if (!cs.length) return base.slice(rs, re)
  const r = []
  let pos = rs
  for (const c of cs) {
    r.push(...base.slice(pos, c.start), ...c.lines)
    pos = c.end
  }
  r.push(...base.slice(pos, re))
  return r
}

export function merge(mode, mine, base, theirs) {
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.start - b.start || a.who - b.who)
  const out = []
  const info = []
  let conflict = false
  let pos = 0
  const stable = to => {
    if (to > pos) { out.push(...base.slice(pos, to)); info.push(`stable ${to - pos}`) }
  }
  let k = 0
  while (k < all.length) {
    const rs = all[k].start
    let re = all[k].end
    const group = [all[k++]]
    while (k < all.length && all[k].start <= re) {
      re = Math.max(re, all[k].end)
      group.push(all[k++])
    }
    stable(rs)
    pos = re
    const cm = group.filter(c => c.who === 0)
    const ct = group.filter(c => c.who === 1)
    const m = sideLines(base, rs, re, cm)
    const t = sideLines(base, rs, re, ct)
    const b = base.slice(rs, re)
    if (group.length === 1) {
      const l = cm.length ? m : t
      out.push(...l)
      info.push(`${cm.length ? 'mine' : 'theirs'} ${l.length}`)
    } else if (eq(m, t)) {
      out.push(...m); info.push(`both ${m.length}`)
    } else if (eq(m, b)) {
      out.push(...t); info.push(`theirs ${t.length}`)
    } else if (eq(t, b)) {
      out.push(...m); info.push(`mine ${m.length}`)
    } else {
      conflict = true
      out.push('<<<<<<< mine', ...m)
      if (mode !== 'merge2') out.push('||||||| base', ...b)
      out.push('=======', ...t, '>>>>>>> theirs')
      info.push(`conflict mine=${m.length} base=${b.length} theirs=${t.length}`)
    }
  }
  stable(base.length)
  return { out: mode === 'regions' ? info : out, conflict }
}
