import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>', '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdChar = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

function scan(text) {
  const s = Array.from(text)
  const n = s.length
  const tokens = []
  let i = 0, line = 1, col = 1

  const adv = () => {
    const c = s[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }

  // digit run with single underscores between digits; returns end index
  const run = (j, ok) => {
    if (!ok(s[j])) return j
    j++
    while (true) {
      if (ok(s[j])) j++
      else if (s[j] === '_' && ok(s[j + 1])) j += 2
      else break
    }
    return j
  }

  while (i < n) {
    const c = s[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') adv()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      const l0 = line, c0 = col
      let depth = 0
      while (true) {
        if (i >= n) throw new ScanError(l0, c0, 'unterminated block comment')
        if (s[i] === '/' && s[i + 1] === '*') { adv(); adv(); depth++ }
        else if (s[i] === '*' && s[i + 1] === '/') { adv(); adv(); depth-- ; if (depth === 0) break }
        else adv()
      }
      continue
    }
    const l0 = line, c0 = col
    if (c === 'r' && s[i + 1] === '"') {
      adv(); adv()
      let v = ''
      while (true) {
        if (i >= n) throw new ScanError(l0, c0, 'unterminated string')
        const d = adv()
        if (d === '"') break
        v += d
      }
      tokens.push({ line: l0, col: c0, kind: 'rawstring', body: JSON.stringify(v) })
      continue
    }
    if (isIdStart(c)) {
      let j = i
      while (isIdChar(s[j])) j++
      const t = s.slice(i, j).join('')
      while (i < j) adv()
      tokens.push({ line: l0, col: c0, kind: KEYWORDS.has(t) ? 'keyword' : 'ident', body: t })
      continue
    }
    if (isDigit(c)) {
      let j = i
      let bad = false
      const p = s[i + 1]
      const radix = c === '0' ? { x: isHex, X: isHex, b: isBin, B: isBin, o: isOct, O: isOct }[p] : undefined
      if (radix) {
        const e = run(i + 2, radix)
        if (e === i + 2) bad = true
        j = e === i + 2 ? i + 2 : e
      } else {
        j = run(i, isDigit)
        if (s[j] === '.' && isDigit(s[j + 1])) j = run(j + 1, isDigit)
        if (s[j] === 'e' || s[j] === 'E') {
          if (isDigit(s[j + 1])) j = run(j + 1, isDigit)
          else if ((s[j + 1] === '+' || s[j + 1] === '-') && isDigit(s[j + 2])) j = run(j + 2, isDigit)
        }
      }
      if (bad || isIdChar(s[j])) {
        while (isIdChar(s[j])) j++
        throw new ScanError(l0, c0, 'invalid number ' + s.slice(i, j).join(''))
      }
      const t = s.slice(i, j).join('')
      while (i < j) adv()
      tokens.push({ line: l0, col: c0, kind: 'number', body: t })
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      while (true) {
        if (i >= n) throw new ScanError(l0, c0, 'unterminated string')
        const el = line, ec = col
        const d = adv()
        if (d === '"') break
        if (d === '\n') throw new ScanError(el, ec, 'newline in string')
        if (d !== '\\') { v += d; continue }
        if (i >= n) throw new ScanError(l0, c0, 'unterminated string')
        const e = adv()
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '0': '\0' }
        if (e in simple) v += simple[e]
        else if (e === 'x') {
          if (isHex(s[i]) && isHex(s[i + 1])) {
            v += String.fromCharCode(parseInt(s[i] + s[i + 1], 16)); adv(); adv()
          } else throw new ScanError(el, ec, 'invalid escape \\x')
