            ok = hex.length > 0 && s[j] === '}' && parseInt(hex, 16) <= 0x10ffff
          }
          if (!ok) throw new ScanError(el, ec, 'invalid escape \\u')
          v += String.fromCodePoint(parseInt(hex, 16))
          while (i <= j) adv()
        } else throw new ScanError(el, ec, 'invalid escape \\' + e)
