const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (v) => ({ t: 'e', v })
const num = (v) => ({ t: 'n', v })

export function parseAddr(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  const col = L.length === 1 ? L.charCodeAt(0) - 64 : 26 + (L.charCodeAt(0) - 65) * 26 + (L.charCodeAt(1) - 64)
  return { col, row, name: L + row }
}
const colName = (c) => (c <= 26 ? String.fromCharCode(64 + c) : String.fromCharCode(65 + Math.floor((c - 27) / 26)) + String.fromCharCode(65 + ((c - 27) % 26)))
const nameOf = (col, row) => colName(col) + row

export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const s = lines[i].replace(/^[ \t]+/, '')
    if (s === '' || s[0] === '#') continue
    const m = /^([^ \t]*)[ \t]*([^]*)$/.exec(s)
    const raw = m[1]
    const a = parseAddr(raw)
    if (!a) return { error: `line ${i + 1}: invalid cell address ${raw.toUpperCase()}` }
    if (cells.has(a.name)) return { error: `line ${i + 1}: cell ${a.name} is declared twice` }
    cells.set(a.name, { col: a.col, row: a.row, name: a.name, content: m[2] })
  }
  const list = [...cells.values()].sort((x, y) => x.col - y.col || x.row - y.row)
  return { cells, list }
}

// ---- parser ----
function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) { toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) { toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue }
    const two = src.slice(i, i + 2)
    if (two === '<>' || two === '<=' || two === '>=') { toks.push({ k: 'op', v: two }); i += 2; continue }
    if ('^*/+-=<>(),:'.includes(c)) { toks.push({ k: 'op', v: c }); i++; continue }
    throw new Error('syntax')
  }
  return toks
}

function parseFormula(src) {
  const toks = tokenize(src)
  let p = 0
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const need = (v) => { if (!isOp(v)) throw new Error('syntax'); p++ }
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { type: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { type: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { type: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { type: 'neg', op, e: unary() } }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) throw new Error('syntax')
    if (t.k === 'num') { p++; return { type: 'num', v: t.v } }
    if (t.k === 'op' && t.v === '(') { p++; const e = cmp(); need(')'); return { type: 'paren', e } }
    if (t.k === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (!isOp(')')) {
          args.push(cmp())
          while (isOp(',')) { p++; args.push(cmp()) }
        }
        need(')')
        return { type: 'call', name: t.v.toUpperCase(), args }
      }
      const u = t.v.toUpperCase()
      if (isOp(':')) {
