function collect(node, acc) {
  switch (node.type) {
    case 'ref': if (node.a) acc.push({ col: node.a.col, row: node.a.row }); break
    case 'range': if (node.a && node.b) acc.push(...cellsOfRange(node)); break
    case 'bin': collect(node.l, acc); collect(node.r, acc); break
    case 'neg': case 'paren': collect(node.e, acc); break
    case 'call': node.args.forEach((a) => collect(a, acc)); break
