// ---- evaluation ----
const toNum = (v) => (v.t === 'n' ? v : v.t === 'b' ? num(v.v ? 1 : 0) : v.t === 's' ? err('#VALUE!') : v)
const fin = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))
