class Fail extends Error {}
const NAME = /^[A-Za-z0-9_.\/:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

function num(text, field, least) {
  if (!UINT.test(text)) throw new Fail(`${field} must be an integer of at least ${least}`)
  const v = BigInt(text)
  if (v < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
  return v
}

function run(input) {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const out = []
  const stats = new Map()
  const states = new Map() // policy name -> Map key -> state
  let started = false
  let lastTick = null
  let allowed = 0n, denied = 0n

  for (let i = 0; i < lines.length; i++) {
    const text = lines[i].trim()
    if (text === '' || text.startsWith('#')) continue
    const f = text.split(/\s+/)
    const n = i + 1
    try {
      const w = f[0]
      if (w === 'bucket' || w === 'window' || w === 'route') {
        if (started) {
          const need = w === 'bucket' ? 5 : w === 'window' ? 4 : 3
          // arity errors take precedence over ordering
          if (w === 'route' ? f.length < need - 0 : f.length !== need) throw new Fail(arity(w))
          throw new Fail('declarations must come before the first event')
        }
      }
      if (w === 'bucket') {
        if (f.length !== 5) throw new Fail(arity(w))
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const capacity = num(f[2], 'capacity', 1)
        const refill = num(f[3], 'refill', 0)
        const per = num(f[4], 'per', 1)
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { name: f[1], type: 'bucket', capacity, refill, per })
        states.set(f[1], new Map())
      } else if (w === 'window') {
        if (f.length !== 4) throw new Fail(arity(w))
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const limit = num(f[2], 'limit', 0)
        const span = num(f[3], 'span', 1)
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { name: f[1], type: 'window', limit, span })
        states.set(f[1], new Map())
      } else if (w === 'route') {
        if (f.length < 3) throw new Fail(arity(w))
        if (!NAME.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
        if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
        for (const p of f.slice(2)) if (!policies.has(p)) throw new Fail(`unknown policy ${p}`)
        routes.set(f[1], f.slice(2))
      } else if (w === 'event') {
        if (f.length !== 3) throw new Fail(arity(w))
        const tick = num(f[1], 'tick', 0)
        if (!NAME.test(f[2])) throw new Fail(`invalid key ${f[2]}`)
        if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
        started = true
        lastTick = tick
        const key = f[2]
        let best = null
        for (const p of routes.keys()) if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
        let refused = null
        if (best !== null) {
          const names = routes.get(best)
          const sts = names.map((nm) => advance(policies.get(nm), states.get(nm), key, tick))
          for (let j = 0; j < names.length; j++) {
            if (!ask(policies.get(names[j]), sts[j])) { refused = names[j]; break }
          }
          if (refused === null) names.forEach((nm, j) => record(policies.get(nm), sts[j], tick))
        }
        let s = stats.get(key)
        if (!s) stats.set(key, (s = { a: 0n, d: 0n }))
        if (refused === null) { s.a++; allowed++ } else { s.d++; denied++ }
        out.push(refused === null ? `${tick} ${key} allow` : `${tick} ${key} deny ${refused}`)
      } else {
        throw new Fail(`unknown directive ${w}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${n}: ${e.message}`)
      throw e
    }
