// bucket tokens are stored scaled by `per` so partial periods stay exact
function advance(p, map, key, tick) {
  let s = map.get(key)
  if (p.type === 'bucket') {
    if (!s) map.set(key, (s = { tokens: p.capacity * p.per, last: tick }))
    else {
      const max = p.capacity * p.per
