      if (s.tokens > max) s.tokens = max
      s.last = tick
    }
  } else {
    if (!s) map.set(key, (s = { ticks: [] }))
    const cut = tick - p.span
    s.ticks = s.ticks.filter((t) => t > cut)
  }
  return s
}
function ask(p, s) {
  return p.type === 'bucket' ? s.tokens >= p.per : BigInt(s.ticks.length) < p.limit
}
function record(p, s, tick) {
  if (p.type === 'bucket') s.tokens -= p.per
  else s.ticks.push(tick)
}

let lines
try {
  lines = run(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
