export function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/s.exec(s)
  return { scheme: m[1], authority: m[2], path: m[3], query: m[4], fragment: m[5] }
}

export function splitAuthority(a) {
  if (a === undefined) return null
  const at = a.lastIndexOf('@')
  const userinfo = at < 0 ? undefined : a.slice(0, at)
  const rest = a.slice(at + 1)
  const colon = rest.indexOf(':', rest.lastIndexOf(']') + 1)
  return colon < 0
    ? { userinfo, host: rest, port: undefined }
    : { userinfo, host: rest.slice(0, colon), port: rest.slice(colon + 1) }
}

export function removeDots(path) {
  let inp = path
  let out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

const TRUNC = /%(?![0-9A-Fa-f]{2})/
const UNRESERVED = /^[A-Za-z0-9\-._~]$/

export function checkTruncated(c, line) {
  const sa = splitAuthority(c.authority)
  const parts = [
    ['path', c.path],
    ['userinfo', sa && sa.userinfo],
    ['host', sa && sa.host],
    ['query', c.query],
