export class ElectionError extends Error {}

const fail = (n, msg) => { throw new ElectionError(n === null ? `error: ${msg}` : `error: line ${n}: ${msg}`) }

export function parseElection(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let names = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    if (t[0] === 'candidates') {
      if (names !== null || ballots.length > 0) fail(n, 'candidates must be declared once, before any ballot')
      if (t.length < 2) fail(n, 'expected candidates <name>...')
      names = []
      for (const name of t.slice(1)) {
        if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(n, `invalid candidate name ${name}`)
        if (names.includes(name)) fail(n, `candidate ${name} is declared twice`)
        names.push(name)
      }
    } else if (t[0] === 'ballot') {
      if (t.length < 3) fail(n, 'expected ballot <count> <candidate>...')
      if (!/^[1-9][0-9]*$/.test(t[1])) fail(n, 'count must be a positive integer')
      const seen = []
      for (const name of t.slice(2)) {
        if (names === null || !names.includes(name)) fail(n, `unknown candidate ${name}`)
        if (seen.includes(name)) fail(n, `candidate ${name} is repeated`)
        seen.push(name)
      }
      ballots.push({ count: BigInt(t[1]), prefs: seen })
    } else fail(n, `unknown directive ${t[0]}`)
  }
  if (names === null) fail(null, 'no candidates')
  return { names, ballots }
}
