const byName = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

export function count({ names, ballots }) {
  const continuing = new Set(names)
  const history = new Map(names.map((n) => [n, []]))
  const rounds = []
  for (;;) {
    const votes = new Map([...continuing].map((n) => [n, 0n]))
    let active = 0n
    for (const b of ballots) {
      const c = b.prefs.find((p) => continuing.has(p))
      if (c !== undefined) { votes.set(c, votes.get(c) + b.count); active += b.count }
    }
    let total = 0n
    for (const b of ballots) total += b.count
    for (const [n, v] of votes) history.get(n).push(v)
    const entries = [...votes].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : byName(a[0], b[0])))
    const round = { entries: entries.map(([n, v]) => [n, v.toString()]), exhausted: (total - active).toString(), eliminated: null }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    for (const [n, v] of entries) if (v * 2n > active) return { rounds, winner: n }
    let min = null
    for (const [, v] of entries) if (min === null || v < min) min = v
    let S = entries.filter(([, v]) => v === min).map(([n]) => n)
    for (let r = 0; S.length > 1 && r < rounds.length; ) {
      const vs = S.map((n) => history.get(n)[r])
      const m = vs.reduce((a, b) => (b < a ? b : a))
      if (vs.every((v) => v === m)) r++
      else { S = S.filter((n, k) => vs[k] === m); r = 0 }
    }
    S.sort(byName)
    const out = S[S.length - 1]
    round.eliminated = out
    continuing.delete(out)
  }
}
