const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

/** Parses an election; throws ParseError with the full message on failure. */
export function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    const fail = (m) => { throw new ParseError(`error: line ${n}: ${m}`) }
    if (t[0] === 'candidates') {
      if (candidates !== null) fail('candidates must be declared once, before any ballot')
      if (t.length < 2) fail('expected candidates <name>...')
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!NAME.test(name)) fail(`invalid candidate name ${name}`)
        if (seen.has(name)) fail(`candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = t.slice(1)
    } else if (t[0] === 'ballot') {
      if (candidates === null) fail('candidates must be declared once, before any ballot')
      if (t.length < 3) fail('expected ballot <count> <candidate>...')
      if (!COUNT.test(t[1])) fail('count must be a positive integer')
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!candidates.includes(name)) fail(`unknown candidate ${name}`)
        if (seen.has(name)) fail(`candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(t[1]), ranks: t.slice(2) })
    } else {
      fail(`unknown directive ${t[0]}`)
    }
  }
  if (candidates === null) throw new ParseError('error: no candidates')
  return { candidates, ballots }
}
"}

{"file_path":"src/count.js","content":"const byCode = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

/** Runs the count; returns { rounds: [{counts, exhausted, eliminated}], winner }. */
export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const rounds = []
  for (;;) {
    const counts = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const pick = b.ranks.find((c) => continuing.has(c))
      if (pick !== undefined) {
        counts.set(pick, counts.get(pick) + b.count)
        active += b.count
      }
    }
    const total = ballots.reduce((s, b) => s + b.count, 0n)
    const round = { counts, exhausted: total - active, eliminated: null }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    for (const [c, v] of counts) if (v * 2n > active) return { rounds, winner: c }
    const victim = pickLoser(rounds, continuing)
    round.eliminated = victim
    continuing.delete(victim)
  }
}

function pickLoser(rounds, continuing) {
  const last = rounds[rounds.length - 1].counts
  const min = (set, r) => set.reduce((m, c) => (rounds[r].counts.get(c) < m ? rounds[r].counts.get(c) : m), rounds[r].counts.get(set[0]))
  let fewest = min([...continuing], rounds.length - 1)
  let set = [...continuing].filter((c) => last.get(c) === fewest)
  outer: while (set.length > 1) {
    for (let r = 0; r < rounds.length; r++) {
      const m = min(set, r)
      const next = set.filter((c) => rounds[r].counts.get(c) === m)
      if (next.length < set.length) {
        set = next
        continue outer
      }
    }
    break
  }
  return set.sort(byCode)[set.length - 1]
}
"}

