/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */
import { readFileSync } from 'node:fs'
import { parse, ParseError } from './parse.js'
import { count } from './count.js'

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
  process.stderr.write('error: usage: cli.js rounds|tally\n')
  process.exit(2)
}

try {
  const result = count(parse(readFileSync(0, 'utf8')))
  let out = ''
  if (mode === 'rounds') {
    result.rounds.forEach((r, i) => {
      const list = [...r.counts].sort((a, b) => (a[1] === b[1] ? (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0) : a[1] > b[1] ? -1 : 1))
      out += `round ${i + 1}: ${list.map(([c, v]) => `${c}=${v}`).join(' ')} exhausted=${r.exhausted}\n`
      if (r.eliminated !== null) out += `eliminated ${r.eliminated}\n`
    })
  } else {
    out += `rounds ${result.rounds.length}\n`
  }
  out += result.winner === null ? 'no winner\n' : `winner ${result.winner}\n`
  process.stdout.write(out)
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write(e.message + '\n')
  process.exit(2)
}
"}

