{"description":"Write cli.js and run tests","command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

function fail(msg, code = 2) {
  process.stderr.write(msg + '\n')
  process.exit(code)
}

const args = process.argv.slice(2)
const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
let mode = args[0]
let workers = 0
if (mode === 'waves' || mode === 'explain') {
  if (args.length !== 1) fail(USAGE)
} else if (mode === 'pack') {
  if (args.length !== 2) fail(USAGE)
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else fail(USAGE)

let input = ''
try { input = readFileSync(0, 'utf8') } catch { input = '' }
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cost = new Map()
const deps = new Map()
const depUses = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    depUses.push(w.slice(1))
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
})
for (const names of depUses) {
  for (const x of names) if (!cost.has(x)) fail(`error: unknown task ${x}`)
}
for (const k of cost.keys()) deps.set(k, new Set())
for (const [a, ...ds] of depUses) for (const d of ds) deps.get(a).add(d)
const names = [...cost.keys()].sort()
const dl = new Map(names.map(k => [k, [...deps.get(k)].sort()]))

// cycle detection
const state = new Map()
const stack = []
function dfs(u) {
  state.set(u, 1)
  stack.push(u)
  for (const v of dl.get(u)) {
    const s = state.get(v)
    if (s === 1) {
      const cyc = stack.slice(stack.indexOf(v)).concat(v)
      fail('error: cycle: ' + cyc.join(' -> '), 3)
    }
    if (!s) dfs(v)
  }
  stack.pop()
  state.set(u, 2)
}
for (const k of names) if (!state.get(k)) dfs(k)

const start = new Map(), finish = new Map(), depth = new Map()
function calc(u) {
  if (finish.has(u)) return
  let s = 0n, d = 0
  for (const v of dl.get(u)) {
    calc(v)
    if (finish.get(v) > s) s = finish.get(v)
    if (depth.get(v) + 1 > d) d = depth.get(v) + 1
  }
  start.set(u, s); finish.set(u, s + cost.get(u)); depth.set(u, d)
}
// iterative-safe enough via recursion order: process by name, recursion depth = chain length
for (const k of names) calc(k)
let total = 0n
for (const k of names) if (finish.get(k) > total) total = finish.get(k)

const out = []
if (mode === 'waves') {
  const ws = []
  for (const k of names) (ws[depth.get(k)] ||= []).push(k)
  ws.forEach((w, i) => out.push(`wave ${i}: ${w.join(' ')}`))
  out.push(`total ${total}`)
} else if (mode === 'explain') {
  for (const k of names) out.push(`${k} start=${start.get(k)} finish=${finish.get(k)} depth=${depth.get(k)}`)
  out.push(`total ${total}`)
} else {
  const prio = new Map()
  const dependents = new Map(names.map(k => [k, []]))
  for (const k of names) for (const d of dl.get(k)) dependents.get(d).push(k)
  function pr(u) {
    if (prio.has(u)) return prio.get(u)
    let m = 0n
    for (const v of dependents.get(u)) { const p = pr(v); if (p > m) m = p }
    prio.set(u, m + cost.get(u))
    return m + cost.get(u)
  }
  for (const k of names) pr(k)
  const order = names.slice().sort((a, b) => (prio.get(a) > prio.get(b) ? -1 : prio.get(a) < prio.get(b) ? 1 : a < b ? -1 : 1))
  const done = new Map() // started tasks -> finish
  const freeAt = new Array(workers).fill(0n)
  const ran = Array.from({ length: workers }, () => [])
  let t = 0n
  let makespan = 0n
  while (done.size < names.length) {
    for (;;) {
      let wi = freeAt.findIndex(f => f <= t)
      if (wi < 0) break
      const task = order.find(u => !done.has(u) && dl.get(u).every(d => done.has(d) && done.get(d) <= t))
      if (!task) break
      const f = t + cost.get(task)
      done.set(task, f)
      freeAt[wi] = f
      ran[wi].push(`${task}@${t}-${f}`)
      if (f > makespan) makespan = f
    }
    if (done.size === names.length) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    for (const f of done.values()) if (f > t && (next === null || f < next)) next = f
