const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const RADIX = { x: isHex, b: (c) => c === '0' || c === '1', o: (c) => c !== undefined && c >= '0' && c <= '7' }

function scan(src) {
  const cs = Array.from(src)
  const n = cs.length
  const tokens = []
  let i = 0, line = 1, col = 1

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col += 4 - ((col - 1) % 4)
    else col++
    return c
  }

  // digit run: digits with single underscores between two digits
  const run = (isD, start) => {
    let j = start
    if (!isD(cs[j])) return j
    j++
    for (;;) {
      if (isD(cs[j])) j++
      else if (cs[j] === '_' && isD(cs[j + 1])) j += 2
      else break
    }
    return j
  }

