    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    const tl = line, tc = col
    const emit = (kind, body) => tokens.push(`${tl}:${tc} ${kind} ${body}`)
    const fail = (reason, l = tl, k = tc) => { throw new ScanError(l, k, reason) }

    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      adv(); adv()
      let depth = 1
      while (depth > 0) {
        if (i >= n) fail('unterminated block comment')
        if (cs[i] === '*' && cs[i + 1] === '/') { adv(); adv(); depth-- }
        else if (cs[i] === '/' && cs[i + 1] === '*') { adv(); adv(); depth++ }
        else adv()
      }
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      adv(); adv()
      let s = ''
      for (;;) {
        if (i >= n) fail('unterminated string')
        const d = adv()
        if (d === '"') break
        s += d
