      while (i < j) s += adv()
      emit('number', s)
      continue
    }
    if (c === '"') {
      adv()
      let s = ''
      for (;;) {
        if (i >= n) fail('unterminated string')
        const bl = line, bc = col
        const d = adv()
        if (d === '"') break
        if (d === '\n') fail('newline in string', bl, bc)
        if (d !== '\\') { s += d; continue }
        if (i >= n) fail('unterminated string')
        const e = cs[i]
        const bad = () => fail(`invalid escape \\${e}`, bl, bc)
