        if (e === 'n') s += '\n'
        else if (e === 't') s += '\t'
        else if (e === 'r') s += '\r'
        else if (e === '\\') s += '\\'
        else if (e === '"') s += '"'
        else if (e === '0') s += '\0'
        else if (e === 'x') {
          if (!isHex(cs[i]) || !isHex(cs[i + 1])) bad()
          s += String.fromCharCode(parseInt(cs[i] + cs[i + 1], 16))
          adv(); adv()
        } else if (e === 'u') {
          if (cs[i] !== '{') bad()
          let j = i + 1, h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (h === '' || cs[j] !== '}') bad()
          const v = parseInt(h.replace(/^0+(?=.)/, ''), 16)
          if (!(v <= 0x10ffff)) bad()
          s += String.fromCodePoint(v)
