    fail(`unexpected character ${c}`)
  }
  return tokens
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }
  const src = readFileSync(0, 'utf8')
  let tokens
  try {
    tokens = scan(src)
  } catch (e) {
    if (!(e instanceof ScanError)) throw e
    process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
    process.exit(2)
  }
  let out = ''
  if (args[0] === 'tokens') out = tokens.map((t) => t + '\n').join('')
  else {
    const counts = Object.fromEntries(KINDS.map((k) => [k, 0]))
    for (const t of tokens) counts[t.split(' ')[1]]++
    for (const k of KINDS) out += `${k} ${counts[k]}\n`
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
}

