{"file_path":"src/addr.js","content":"// Address: { col: 1..702, row: 1..999 }
export function parseAddress(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  const col = L.length === 1 ? L.charCodeAt(0) - 64 : (L.charCodeAt(0) - 64) * 26 + (L.charCodeAt(1) - 64)
  return { col, row }
}

export function colIndex(a) {
  return a.col
}

export function formatAddress(a) {
  const c = a.col
  const L = c <= 26 ? String.fromCharCode(64 + c) : String.fromCharCode(64 + Math.floor((c - 1) / 26)) + String.fromCharCode(65 + ((c - 1) % 26))
  return L + a.row
}
"}

{"file_path":"src/parse.js","content":"// Returns an AST, or null when the grammar rejects the body.
class Reject extends Error {}

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length
    } else if ((m = /^(<>|<=|>=|[<>=+\-*\/^(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] }); i += m[0].length
    } else throw new Reject()
  }
  return toks
}

export function parseFormula(body) {
  try {
    const toks = tokenize(body)
    let p = 0
    const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
    const expect = (v) => { if (!isOp(v)) throw new Reject(); p++ }

    const CMP = ['=', '<>', '<', '<=', '>', '>=']
    function cmp() {
      let l = add()
      while (p < toks.length && toks[p].k === 'op' && CMP.includes(toks[p].v)) {
        const op = toks[p++].v
        l = { t: 'bin', op, l, r: add() }
      }
      return l
    }
    function add() {
      let l = mul()
      while (isOp('+') || isOp('-')) {
        const op = toks[p++].v
        l = { t: 'bin', op, l, r: mul() }
      }
      return l
    }
    function mul() {
      let l = pow()
      while (isOp('*') || isOp('/')) {
        const op = toks[p++].v
        l = { t: 'bin', op, l, r: pow() }
      }
      return l
    }
    function pow() {
      const l = unary()
      if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
      return l
    }
    function unary() {
      if (isOp('-') || isOp('+')) {
        const op = toks[p++].v
        return { t: 'un', op, e: unary() }
      }
      return primary()
    }
    function primary() {
      if (p >= toks.length) throw new Reject()
      const tk = toks[p]
      if (tk.k === 'num') { p++; return { t: 'num', v: tk.v } }
      if (tk.k === 'op') {
        if (tk.v === '(') { p++; const e = cmp(); expect(')'); return e }
        throw new Reject()
      }
      p++
      if (isOp('(')) {
        p++
        const args = []
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          expect(')')
          break
        }
        return { t: 'call', name: tk.v.toUpperCase(), args }
      }
      const up = tk.v.toUpperCase()
      if (up === 'TRUE') return { t: 'bool', v: true }
      if (up === 'FALSE') return { t: 'bool', v: false }
      return { t: 'ref', name: tk.v }
    }
    function arg() {
      if (
        p + 2 < toks.length && toks[p].k === 'word' && toks[p + 1].k === 'op' && toks[p + 1].v === ':' && toks[p + 2].k === 'word'
      ) {
        const after = toks[p + 3]
        if (after && after.k === 'op' && (after.v === ',' || after.v === ')')) {
          const r = { t: 'range', a: toks[p].v, b: toks[p + 2].v }
          p += 3
          return r
        }
        throw new Reject()
      }
      return cmp()
    }
    const ast = cmp()
    if (p !== toks.length) throw new Reject()
    return ast
  } catch (e) {
    if (e instanceof Reject) return null
    throw e
  }
}
"}

{"file_path":"src/eval.js","content":"import { parseFormula } from './parse.js'
import { parseAddress, formatAddress } from './addr.js'

const ERRORS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const err = (e) => ({ k: 'err', v: e })
const num = (v) => (Number.isFinite(v) ? { k: 'num', v } : err('#DIV/0!'))
const ZERO = { k: 'num', v: 0 }

function toNum(x) {
  if (x.k === 'num') return x
  if (x.k === 'bool') return { k: 'num', v: x.v ? 1 : 0 }
  if (x.k === 'text') return err('#VALUE!')
  return x
}

const RANK = { num: 0, text: 1, bool: 2 }
function cmpCodePoints(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
function compare(a, b) {
  if (a.k !== b.k) return RANK[a.k] - RANK[b.k]
  if (a.k === 'text') return cmpCodePoints(a.v, b.v)
  if (a.k === 'bool') return Number(a.v) - Number(b.v)
  return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
}

export class Sheet {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.busy = new Set()
  }

  print(v) {
    if (v.k === 'num') return String(Number(v.v.toPrecision(10)))
    if (v.k === 'bool') return v.v ? 'TRUE' : 'FALSE'
    return v.v
  }

  get(key) {
    if (this.memo.has(key)) return this.memo.get(key)
    const c = this.cells.get(key)
    if (!c) return ZERO
    if (this.busy.has(key)) return err('#CYCLE!')
    this.busy.add(key)
    let v
    const s = c.content
    if (s[0] === '=') {
      const ast = parseFormula(s.slice(1))
      v = ast ? this.ev(ast) : err('#ERR!')
    } else if (s === '') v = ZERO
    else if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) v = { k: 'num', v: Number(s) }
    else if (ERRORS.has(s)) v = err(s)
    else v = { k: 'text', v: s }
    this.busy.delete(key)
    this.memo.set(key, v)
    return v
  }

  ref(name) {
    const a = parseAddress(name)
    return a ? this.get(formatAddress(a)) : err('#REF!')
  }

  ev(n) {
    switch (n.t) {
      case 'num': return { k: 'num', v: n.v }
      case 'bool': return { k: 'bool', v: n.v }
      case 'ref': return this.ref(n.name)
      case 'range': return err('#ERR!')
      case 'un': {
        const e = toNum(this.ev(n.e))
        if (e.k === 'err') return e
        return n.op === '-' ? num(-e.v) : e
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
  }

  bin(n) {
    const l = this.ev(n.l)
    if (l.k === 'err') return l
    const r = this.ev(n.r)
    if (r.k === 'err') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      const c = compare(l, r)
      const v = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
      return { k: 'bool', v }
    }
    const a = toNum(l)
    if (a.k === 'err') return a
    const b = toNum(r)
    if (b.k === 'err') return b
    switch (n.op) {
      case '+': return num(a.v + b.v)
      case '-': return num(a.v - b.v)
      case '*': return num(a.v * b.v)
      case '/': return b.v === 0 ? err('#DIV/0!') : num(a.v / b.v)
      case '^': return num(Math.pow(a.v, b.v))
    }
  }

  call(n) {
    const name = n.name
    const args = n.args
    if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'].includes(name)) return err('#NAME?')
    if (name === 'ABS' && args.length !== 1) return err('#ERR!')
    if (name === 'IF' && args.length !== 3) return err('#ERR!')
    if (name === 'IF' || name === 'ABS') {
      if (args.some((a) => a.t === 'range')) return err('#ERR!')
    }
    if (name === 'IF') {
      const c = this.ev(args[0])
      if (c.k === 'err') return c
      let t
      if (c.k === 'bool') t = c.v
      else if (c.k === 'num') t = c.v !== 0
      else return err('#VALUE!')
      return this.ev(args[t ? 1 : 2])
    }
    const vals = []
    for (const a of args) {
      if (a.t === 'range') {
        const p = parseAddress(a.a), q = parseAddress(a.b)
        if (!p || !q) { vals.push(err('#REF!')); continue }
        const c1 = Math.min(p.col, q.col), c2 = Math.max(p.col, q.col)
        const r1 = Math.min(p.row, q.row), r2 = Math.max(p.row, q.row)
        for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) vals.push(this.get(formatAddress({ col: c, row: r })))
      } else vals.push(this.ev(a))
    }
    const e = vals.find((v) => v.k === 'err')
    if (e) return e
    if (name === 'COUNT') return { k: 'num', v: vals.filter((v) => v.k === 'num').length }
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.k === 'err') return x
      nums.push(x.v)
    }
    switch (name) {
      case 'ABS': return num(Math.abs(nums[0]))
      case 'SUM': return num(nums.reduce((a, b) => a + b, 0))
      case 'MIN': return num(Math.min(...nums))
      case 'MAX': return num(Math.max(...nums))
      case 'AVG': return num(nums.reduce((a, b) => a + b, 0) / nums.length)
    }
  }
}
"}

