{"file_path":"src/cli.js","content":"#!/usr/bin/env node
import { readFileSync } from 'node:fs'
import { parseFormula } from './parse.js'
import { Sheet } from './eval.js'
import { parseAddress, formatAddress } from './addr.js'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  fail('error: usage: cli.js values|deps')
}
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const word = /^[^ \t]*/.exec(s)[0]
  const addr = parseAddress(word)
  if (!addr) fail(`error: line ${i + 1}: invalid cell address ${word}`)
  const key = formatAddress(addr)
  if (cells.has(key)) fail(`error: line ${i + 1}: cell ${key} is declared twice`)
  const content = s.slice(word.length).replace(/^[ \t]+/, '')
  cells.set(key, { addr, content })
}

const sorted = [...cells.values()].sort((a, b) => a.addr.col - b.addr.col || a.addr.row - b.addr.row)

function add(set, a) {
  if (a) set.set(formatAddress(a), a)
}
function collect(n, set) {
  switch (n.t) {
    case 'ref': add(set, parseAddress(n.name)); break
    case 'range': {
      const a = parseAddress(n.a)
      const b = parseAddress(n.b)
      if (!a || !b) break
      const c1 = Math.min(a.col, b.col), c2 = Math.max(a.col, b.col)
      const r1 = Math.min(a.row, b.row), r2 = Math.max(a.row, b.row)
      for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) add(set, { col: c, row: r })
      break
    }
    case 'bin': collect(n.l, set); collect(n.r, set); break
    case 'un': collect(n.e, set); break
    case 'call': for (const x of n.args) collect(x, set); break
  }
}

const res = []
if (mode === 'values') {
  const sheet = new Sheet(cells)
  for (const c of sorted) {
    const k = formatAddress(c.addr)
    res.push(`${k}=${sheet.print(sheet.get(k))}\n`)
  }
} else {
  for (const c of sorted) {
    let line = formatAddress(c.addr) + ':'
    if (c.content[0] === '=') {
      const ast = parseFormula(c.content.slice(1))
      if (ast) {
        const set = new Map()
        collect(ast, set)
        const list = [...set.values()].sort((a, b) => a.col - b.col || a.row - b.row)
        for (const a of list) line += ' ' + formatAddress(a)
      }
    }
    res.push(line + '\n')
  }
}
process.stdout.write(res.join(''))
"}

